import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT SIDE */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Thinker • Problem Solver
          </h2>

          <p className="desc">
            I build structured systems, clean interfaces, and real-world applications
            that focus on clarity, performance, and meaningful impact.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>

            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT SIDE - SVG ORBIT SYSTEM */}
        <div className="right">

          <div className="orbitBox">

            {/* SVG BACKGROUND ORBITS */}
            <svg className="orbitSvg" viewBox="0 0 300 300">

              {/* OUTER RING */}
              <circle
                cx="150"
                cy="150"
                r="120"
                fill="none"
                stroke="rgba(56,189,248,0.15)"
                strokeWidth="1"
                strokeDasharray="6 6"
                className="rotateSlow"
              />

              {/* INNER RING */}
              <circle
                cx="150"
                cy="150"
                r="85"
                fill="none"
                stroke="rgba(56,189,248,0.2)"
                strokeWidth="1"
                strokeDasharray="4 6"
                className="rotateReverse"
              />

              {/* ORBIT PATH */}
              <path
                id="orbitPath"
                d="M150,30
                   a120,120 0 1,1 0,240
                   a120,120 0 1,1 0,-240"
                fill="none"
              />

              {/* MOVING DOT */}
              <circle r="5" fill="#38BDF8">
                <animateMotion dur="6s" repeatCount="indefinite">
                  <mpath href="#orbitPath" />
                </animateMotion>
              </circle>

            </svg>

            {/* CENTER AVATAR */}
            <div className="centerAvatar">
              <img
                src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
                alt="avatar"
              />
              <p>Swetha A</p>
            </div>

            {/* TECH LABELS */}
            <div className="chip react">React</div>
            <div className="chip java">Java</div>
            <div className="chip spring">Spring Boot</div>
            <div className="chip python">Python</div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT SIDE */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
          margin-bottom: 15px;
        }

        h1 {
          font-size: 62px;
          margin: 0;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
          margin-top: 10px;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          cursor: pointer;
          transition: 0.3s;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* RIGHT SIDE */
        .orbitBox {
          position: relative;
          width: 340px;
          height: 340px;
          margin: auto;
        }

        .orbitSvg {
          position: absolute;
          width: 100%;
          height: 100%;
        }

        /* ROTATION */
        .rotateSlow {
          animation: spin 20s linear infinite;
          transform-origin: center;
        }

        .rotateReverse {
          animation: spinReverse 14s linear infinite;
          transform-origin: center;
        }

        @keyframes spin {
          100% { transform: rotate(360deg); }
        }

        @keyframes spinReverse {
          100% { transform: rotate(-360deg); }
        }

        /* CENTER AVATAR */
        .centerAvatar {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%,-50%);
          text-align: center;
          z-index: 2;
        }

        .centerAvatar img {
          width: 95px;
          height: 95px;
          border-radius: 50%;
          border: 2px solid rgba(56,189,248,0.4);
          box-shadow: 0 0 25px rgba(56,189,248,0.15);
        }

        .centerAvatar p {
          font-size: 13px;
          color: #94a3b8;
          margin-top: 6px;
        }

        /* TECH CHIPS */
        .chip {
          position: absolute;
          padding: 7px 11px;
          border-radius: 20px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          font-size: 12px;
          color: #cbd5e1;
        }

        .react { top: 8%; left: 45%; }
        .java { top: 45%; right: 0; }
        .spring { bottom: 20%; right: 18%; }
        .python { bottom: 8%; left: 40%; }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          h1 {
            font-size: 42px;
          }

          .buttons {
            justify-content: center;
          }

          .orbitBox {
            margin-top: 40px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
